def normalize(s):
    return ''.join(c for c in unicodedata.normalize('NFKD',str(s).lower().replace('ł','l')) if not unicodedata.combining(c))


def scan(text, source):
    result=[]; lines=text.splitlines()
    for n,line in enumerate(lines):
        line=re.sub(r'\s+',' ',line).strip()
        if not line: continue
        for area,topic,pattern in RULES+SPECIAL:
            if not pattern.search(line): continue
            context=' '.join(x.strip() for x in lines[max(0,n-1):n+2] if x.strip())
            context=re.sub(r'\s+',' ',context)
            notes=[]
            if re.search(r'[☐☑☒□■✓✔]|\[[ xX]\]',context):
                notes.append('Formularz: zweryfikuj wybór na oryginale; opcja nie została uznana za obowiązującą.')
            if re.search(r'\b(no|not|nicht|kein\w*|non|sans|hors\s+lot|nie)\b',context,re.I):
                notes.append('Możliwe wyłączenie lub negacja: sprawdź kontekst.')
            if 'nordec' in context.lower(): notes.append('Sprawdź, czy dokument jest wzorem, czy wymaganiem projektu.')
            if re.search(r'(?:see|voir|siehe|wg|patrz)\s',context,re.I): notes.append('Sprawdź kompletność dokumentu wskazanego w odsyłaczu.')
            result.append(Evidence(area,topic,context,f'{source}, wiersz {n+1}',note=' '.join(notes),match_text=line))
    return result


def decode(data):
    for enc in ['utf-8-sig','utf-16','cp1250','cp1252']:
        try: return data.decode(enc)
        except UnicodeError: pass
    raise ValueError('Nie rozpoznano kodowania tekstu.')


def checked_zip(data):
    z=zipfile.ZipFile(io.BytesIO(data))
    info=z.infolist()
    if len(info)>MAX_MEMBERS: z.close();raise ValueError('Archiwum zawiera zbyt wiele plików.')
    if sum(x.file_size for x in info)>MAX_BATCH: z.close();raise ValueError('Za duże archiwum po rozpakowaniu (limit 500 MB).')
    for x in info:
        if x.flag_bits & 1: z.close();raise ValueError('Archiwum zaszyfrowane; prześlij paczkę bez hasła.')
        if x.file_size>MAX_FILE: z.close();raise ValueError('Pojedynczy plik przekracza limit 100 MB.')
    return z


def extract(data, suffix, source):
    """Yield (location, text). No filesystem extraction for archives."""
    if suffix=='.pdf':
        with fitz.open(stream=data,filetype='pdf') as doc:
            if doc.needs_pass: raise ValueError('PDF zabezpieczony hasłem.')
            if len(doc)>2000: raise ValueError('PDF ma więcej niż 2000 stron.')
            for i,page in enumerate(doc,1):
                text=page.get_text('text',sort=True)
                widgets=list(page.widgets() or [])
                if widgets:
                    text+='\nPOLA FORMULARZA:\n'+'\n'.join(f'{w.field_name}: {w.field_value}' for w in widgets)
                annot=page.first_annot
                while annot:
                    content=annot.info.get('content','')
                    if content:text+='\nADNOTACJA PDF: '+content
                    annot=annot.next
                if len(text.strip())<25:
                    text+='\n[DO WYJAŚNIENIA: strona bez wystarczającej warstwy tekstowej; wymaga OCR / przeglądu wizualnego.]'
                yield f'{source}, s. {i}',text
    elif suffix=='.docx':
        with checked_zip(data) as z:
            names=[n for n in z.namelist() if re.fullmatch(r'word/(document|header\d+|footer\d+)\.xml',n)]
            ns={'w':'http://schemas.openxmlformats.org/wordprocessingml/2006/main'}
            for name in names:
                root=ET.fromstring(z.read(name));lines=[]
                for node in root.findall('.//w:p',ns):
                    txt=''.join(x.text or '' for x in node.findall('.//w:t',ns))
                    for cb in node.findall('.//{http://schemas.microsoft.com/office/word/2010/wordml}checkbox'):
                        checked=cb.find('{http://schemas.microsoft.com/office/word/2010/wordml}checked')
                        txt=('☑ ' if checked is not None and checked.get('{http://schemas.microsoft.com/office/word/2010/wordml}val')=='1' else '☐ ')+txt
                    lines.append(txt)
                yield f'{source}, {name}', '\n'.join(lines)
    elif suffix in {'.xlsx','.xlsm'}:
        with checked_zip(data): pass
        wb=openpyxl.load_workbook(io.BytesIO(data),read_only=True,data_only=False,keep_links=False)
        try:
            for ws in wb:
                if ws.max_row>MAX_ROWS: raise ValueError('Arkusz przekracza limit 200 000 wierszy.')
                lines=[]
                for cells in ws.iter_rows():
                    values=[f'{c.coordinate}: {c.value}' for c in cells if c.value is not None]
                    if values:lines.append(' | '.join(values))
                yield f'{source}, arkusz {ws.title}', '\n'.join(lines)
        finally:wb.close()
    else:
        text=decode(data)
        if suffix=='.ifc':
            # IFC is inspected as STEP text only; quantities are not interpreted as BOM.
            lines=[l for l in text.splitlines() if any(t in l for t in ['FILE_NAME(','FILE_SCHEMA(','IFCMATERIAL(','IFCPROPERTYSINGLEVALUE(','IFCPROJECT('])]
            text='\n'.join(lines)
        yield source,text


def analyse(paths,clipboard='',progress=lambda *a:None):
    session=Session();seen=set();budget=[0]
    def add(data,source,suffix):
        if len(data)>MAX_FILE:raise ValueError('Plik przekracza limit 100 MB.')
        digest=hashlib.sha256(data).hexdigest()
        if digest in seen:
            session.inventory.append(Inventory(source,'Duplikat','Identyczne bajty; pominięto powtórną analizę.',digest));return
        seen.add(digest)
        if suffix=='.zip':
            with checked_zip(data) as z:
                session.inventory.append(Inventory(source,'Paczka ZIP',f'{len(z.infolist())} wpisów',digest))
                for item in z.infolist():
                    if item.is_dir():continue
                    name=f'{source} > {item.filename}';ext=Path(item.filename).suffix.lower()
                    if ext not in SUPPORTED:
                        session.inventory.append(Inventory(name,'Nie przeanalizowano','Nieobsługiwany format / zagnieżdżone archiwum.'));continue
                    try:add(z.read(item),name,ext)
                    except Exception as exc:session.inventory.append(Inventory(name,'Błąd',str(exc)))
            return
        if suffix not in SUPPORTED:
            session.inventory.append(Inventory(source,'Nie przeanalizowano','Format nieobsługiwany. DWG/DXF i skany wymagają eksportu do tekstowego PDF / OCR.'));return
        budget[0]+=len(data)
        if budget[0]>MAX_BATCH: raise ValueError('Przekroczono 500 MB danych w jednej analizie.')
        parts=list(extract(data,suffix,source))
        session.raw.extend(parts)
        for location,text in parts:
            session.evidence.extend(scan(text,location))
            if 'DO WYJAŚNIENIA: strona' in text:
                session.evidence.append(Evidence('Dokumentacja','OCR / przegląd wizualny','Nie odczytano pełnej treści strony.',location,'Do wyjaśnienia','Skany i graficzne oznaczenia nie są interpretowane automatycznie.'))
        detail=f'Odczytano {len(parts)} części. Wyniki wymagają przeglądu.'
        if suffix=='.ifc':detail+=' IFC: tylko właściwości tekstowe; bez geometrii, przypisań i obliczeń masy.'
        if suffix=='.docx':detail+=' Obrazy i obiekty osadzone wymagają przeglądu ręcznego.'
        if suffix in {'.xlsx','.xlsm'}:detail+=' Formuły pokazano jako tekst; nie są przeliczane.'
        session.inventory.append(Inventory(source,'Odczytano tekst',detail,digest))
    for n,path in enumerate(paths,1):
        progress(n-1,len(paths),f'Czytanie: {Path(path).name}')
        try:
            path=Path(path)
            if path.stat().st_size>MAX_FILE:raise ValueError('Plik przekracza limit 100 MB.')
            add(path.read_bytes(),path.name,path.suffix.lower())
        except Exception as exc:session.inventory.append(Inventory(str(path),'Błąd',str(exc)))
    if clipboard.strip():
        session.raw.append(('Schowek / tekst ręczny',clipboard));session.evidence.extend(scan(clipboard,'Schowek / tekst ręczny'))
    dedup={}
    for e in session.evidence:dedup[(e.area,e.topic,e.text,e.source)]=e
    session.evidence=list(dedup.values())
    progress(len(paths),len(paths),'Analiza zakończona')
    return session


def number(value):
    if isinstance(value,bool):raise ValueError('Wartość logiczna zamiast liczby.')
    if isinstance(value,(int,float)):v=float(value)
    else:
        s=str(value).strip().replace('\xa0','').replace(' ','')
        if ',' in s and '.' in s: raise ValueError('Niejednoznaczny separator liczby.')
        v=float(s.replace(',','.'))
    if not math.isfinite(v) or v<0:raise ValueError('Liczba musi być skończona i nieujemna.')
    return v

BOM_HEADERS=['Pozycja','Profil','Gatunek','Ilość szt','Długość','Jednostka długości','kg/m','Masa podana kg','Masa obliczona kg','Status','Źródło']
ALIASES={
'position':{'pozycja','position','repere','mark'},
'profile':{'profil','profile','type'},'grade':{'gatunek','steel grade','nuance','stahlgute'},
'qty':{'ilosc szt','ilosc','quantity','nombre','anzahl'},'length':{'dlugosc','length','longueur','lange'},
'unit':{'jednostka dlugosci','length unit','unit'},'kgm':{'kg/m','kg per m'},'mass':{'masa kg','masa podana kg','mass kg','poids total kg'}}


def parse_bom(rows,source):
    rows=list(rows)
    if len(rows)>MAX_ROWS:raise ValueError('BOM przekracza limit 200 000 wierszy.')
    if not rows:raise ValueError('Pusta tabela BOM.')
    headers=[normalize(x or '').strip() for x in rows[0]];mapping={}
    for key,aliases in ALIASES.items():
        matches=[i for i,h in enumerate(headers) if h in aliases]
        if len(matches)>1:raise ValueError(f'Niejednoznaczna kolumna: {key}')
        if matches:mapping[key]=matches[0]
    if not {'profile','qty'}.issubset(mapping):raise ValueError('Wymagane nagłówki: Profil i Ilość szt. Użyj szablonu BOM.')
    result=[]
    for index,row in enumerate(rows[1:],2):
        if not any(v is not None and str(v).strip() for v in row):continue
        get=lambda k:row[mapping[k]] if k in mapping and mapping[k]<len(row) else None
        raw={k:get(k) for k in ALIASES};status=[];calc=None
        qty=length=kgm=mass=None
        for key in ['qty','length','kgm','mass']:
            val=raw[key]
            if val is None or str(val).strip()=='':continue
            try:
                parsed=number(val)
                if key=='qty' and (parsed==0 or not parsed.is_integer()):raise ValueError('Ilość sztuk musi być dodatnią liczbą całkowitą.')
                if key in {'length','kgm'} and parsed==0:raise ValueError('Wartość musi być dodatnia.')
                if key=='qty':qty=parsed
                elif key=='length':length=parsed
                elif key=='kgm':kgm=parsed
                else:mass=parsed
            except Exception as exc:status.append(f'{key}: {exc}')
        if qty is None:status.append('Do wyjaśnienia: ilość')
        if not raw['profile']:status.append('Do wyjaśnienia: profil')
        if not raw['grade']:status.append('Do wyjaśnienia: gatunek')
        unit=str(raw['unit'] or '').strip().lower()
        if length is not None and unit not in {'m','mm'}:status.append('Do wyjaśnienia: jednostka długości (m/mm)')
        if qty is not None and length is not None and kgm is not None and unit in {'m','mm'}:
            calc=qty*length*(.001 if unit=='mm' else 1)*kgm
            if mass is not None and abs(calc-mass)>max(.01,abs(mass)*.005):status.append('Do wyjaśnienia - rozbieżność mas (>0,5% lub 0,01 kg)')
        if mass is None and calc is None:status.append('Do wyjaśnienia: masa lub dane do jej obliczenia')
        result.append([raw['position'] or '',raw['profile'] or '',raw['grade'] or '',qty if qty is not None else str(raw['qty'] or ''),length if length is not None else str(raw['length'] or ''),unit,kgm if kgm is not None else str(raw['kgm'] or ''),mass if mass is not None else str(raw['mass'] or ''),round(calc,4) if calc is not None else '', '; '.join(status) or 'Dane kompletne - sprawdź źródło',f'{source}, wiersz {index}'])
    return result


def load_bom(path):
    path=Path(path)
    if path.stat().st_size>MAX_FILE:raise ValueError('BOM przekracza limit 100 MB.')
    if path.suffix.lower()=='.csv':
        text=decode(path.read_bytes())
        try:dialect=csv.Sniffer().sniff(text[:8192],delimiters=';,\t')
        except csv.Error:dialect=csv.excel;dialect.delimiter=';'
        return parse_bom(csv.reader(io.StringIO(text),dialect),path.name)
    if path.suffix.lower()!='.xlsx':raise ValueError('BOM: wybierz CSV lub XLSX.')
    if path.stat().st_size>MAX_FILE:raise ValueError('BOM przekracza limit 100 MB.')
    with checked_zip(path.read_bytes()):pass
    wb=openpyxl.load_workbook(path,read_only=True,data_only=False,keep_links=False)
    try:
        if wb.active.max_row>MAX_ROWS:raise ValueError('Za dużo wierszy BOM.')
        return parse_bom(wb.active.iter_rows(values_only=True),f'{path.name}, arkusz {wb.active.title}')
    finally:wb.close()


PARAMETERS = re.compile(
    r'(?:NF\s*)?(?:EN\s*)?(?:ISO\s*)?(?:EN|ISO)\s*\d{3,5}(?:\s*[-/]\s*\d+)*(?:\s*:\s*\d{4})?'
    r'|\bEXC\s*[-]?\s*[1-4]\b'
    r'|\bS\s*(?:235|275|355|420|460|500|690)(?:J[0R2]|K2|NL?|ML?|QL?1?)?(?:\+[A-Z]+)*\b'
    r'|\bRAL\s*\d{4}\b|\bSa\s*2[.,]5\b|\bP[1-3]\b|\bC[1-5](?:-[HM])?\b|\b(?:REI|EI|R)\s*\d{2,3}\b'
    r'|\b(?:VT|UT|MT|PT|RT)\b|\b(?:PRS|IW|HWS|IKS)\b'
    r'|\bM\s*\d+(?:\s*[x×]\s*\d+(?:[.,]\d+)?)?\b'
    r'|[±]?\d+(?:[.,]\d+)?\s*(?:µm|μm|mm|cm|kg/m|kg|tonnes?|tons?|to|m²|m2|m3|m|t|%|szt\.?)(?!\w)'
    r'|\b(?:DAP|EXW|FCA|DDP|FOB|CIF)\b'
    r'|\b\d{1,2}[./-]\d{1,2}[./-]\d{4}\b',re.I)


def compact_fragments(evidence,limit=3):
    topics={};sources=[];notes=[]
    for e in evidence:
        values=topics.setdefault(e.topic,[])
        for match in PARAMETERS.finditer(e.match_text or e.text):
            value=re.sub(r'\s+',' ',match.group()).strip()
            if normalize(value) not in [normalize(v) for v in values]:values.append(value)
        if e.source not in sources:sources.append(e.source)
        if e.note and e.note not in notes:notes.append(e.note)
    summaries=[]
    for topic,values in topics.items():
        summaries.append(topic+': '+('; '.join(values) if values else 'do wyjaśnienia — opis w dokumentacji'))
    refs='; '.join(sources[:2])+(f' (+{len(sources)-2} lokalizacji)' if len(sources)>2 else '')
    return '\n'.join(summaries),refs,'\n'.join(dict.fromkeys(notes))


def tech_rows(session):
    groups={}
    for e in session.evidence:
        if e.area=='Dodatkowe uwagi technologiczne':groups.setdefault(e.topic,[]).append(e)
    rows=[]
    for topic,es in groups.items():
        values=[];refs=[]
        for e in es:
            for match in PARAMETERS.finditer(e.match_text or e.text):
                v=re.sub(r'\s+',' ',match.group()).strip()
                if normalize(v) not in [normalize(x) for x in values]:values.append(v)
            if e.source not in refs:refs.append(e.source)
        rows.append([topic,'; '.join(values) or 'Zapis występuje w dokumentacji','; '.join(refs[:2])+(f' (+{len(refs)-2} lokalizacji)' if len(refs)>2 else ''),'Do wyjaśnienia — zakres i szczegóły',''])
    return rows


def card(session):
    rows=[]
    for area in AREAS:
        es=[e for e in session.evidence if e.area==area and e.status!='Nie obowiązuje']
        if session.automatic:
            requirement,sources,extra=compact_fragments(es)
            if es:
                missing='Do wyjaśnienia — weryfikacja zakresu i kontekstu.'
                if extra:missing+='\n'+extra
            else:missing='Do wyjaśnienia — brak wymagania w odczytanym tekście.'
            rows.append([area,requirement or 'Do wyjaśnienia',sources,missing])
            continue
        confirmed=[e for e in es if e.status=='Potwierdzone']
        requirement='\n'.join(dict.fromkeys(e.text for e in confirmed)) or 'Do wyjaśnienia - brak potwierdzonego wymagania.'
        sources='\n'.join(dict.fromkeys(e.source for e in confirmed))
        missing=[e.note for e in confirmed if e.note]
        if any(e.status=='Do weryfikacji' for e in es):missing.append('Są znalezione fragmenty do weryfikacji.')
        missing.extend(f'{e.status}: {e.note or e.text} [{e.source}]' for e in es if e.status.startswith('Do wyjaśnienia'))
        rows.append([area,requirement,sources,'\n'.join(dict.fromkeys(missing)) or ('Do wyjaśnienia' if not confirmed else '')])
    return rows


def safe_cell(value):
    # Preserve literal text; never export executable spreadsheet formulas from documents.
    if isinstance(value,str) and value.lstrip().startswith(('=','+','-','@')):return "'"+value
    return value


def export_xlsx(session,path):
    wb=openpyxl.Workbook();wb.remove(wb.active)
    tables=[('Projekt',['Pole','Wartość'],[['Projekt',session.project or 'Do wyjaśnienia'],['Klient',session.client or 'Do wyjaśnienia'],['Numer / rewizja',session.revision or 'Do wyjaśnienia'],['Raport',datetime.now().isoformat(timespec='seconds')],['Zasada','Zapisy źródłowe do weryfikacji; bez domyślnych parametrów.' if session.automatic else 'Tylko ręcznie potwierdzone ustalenia trafiają do wymagań.']]),
    ('Karta wymagań',['Obszar','Wymaganie','Norma / źródło','Braki / do wyjaśnienia'],card(session)),
    ('Uwagi technologiczne',['Temat','Parametry','Źródło','Braki','Uwagi'],tech_rows(session)),
    ('Wszystkie ustalenia',['Obszar','Temat','Fragment źródła','Źródło','Status','Uwagi'],[[e.area,e.topic,e.text,e.source,e.status,e.note] for e in session.evidence]),
    ('BOM',BOM_HEADERS,session.bom),
    ('Pliki',['Plik','Status','Szczegóły','SHA256'],[[i.source,i.status,i.detail,i.sha256] for i in session.inventory])]
    for title,headers,rows in tables:
        ws=wb.create_sheet(title);ws.append(headers)
        for row in rows:ws.append([safe_cell(v) for v in row])
        if title=='Wszystkie ustalenia':ws.sheet_state='hidden'
        ws.freeze_panes='A2';ws.auto_filter.ref=ws.dimensions
        for cell in ws[1]:cell.fill=PatternFill('solid',fgColor='B52832');cell.font=Font(color='FFFFFF',bold=True)
        for row in ws.iter_rows(min_row=2):
            for cell in row:cell.alignment=Alignment(vertical='top',wrap_text=True)
        for col in ws.columns:
            letter=col[0].column_letter
            ws.column_dimensions[letter].width= min(80,max(18,max(len(str(c.value or '')) for c in col[:80])+2))
        ws.sheet_properties.pageSetUpPr.fitToPage=True
        ws.page_setup.orientation='landscape';ws.page_setup.paperSize=ws.PAPERSIZE_A4
        ws.page_setup.fitToWidth=1;ws.page_setup.fitToHeight=0
        ws.print_title_rows='1:1'
    wb.save(path)


def export_html(session,path):
    esc=lambda s:html.escape(str(s)).replace('\n','<br>')
    def table(headers,rows):
        return '<table><thead><tr>'+''.join('<th>'+esc(x)+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table>'
    content='<!doctype html><html lang="pl"><meta charset="utf-8"><title>Zekon - karta wymagań</title><style>body{font:11px Arial;color:#20272d;margin:30px}header{display:flex;align-items:center;gap:24px;border-bottom:3px solid #b52832}img{width:100px}h1{font-size:24px}h2{font-size:17px;color:#b52832;margin-top:24px}table{border-collapse:collapse;width:100%;table-layout:fixed}th,td{border:1px solid #adb8c0;padding:7px;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{background:#e5ebef}tr{break-inside:avoid}.note{background:#fff3df;padding:12px}@media print{body{margin:0;font-size:10px}@page{size:A4 landscape;margin:12mm}thead{display:table-header-group}h2{break-after:avoid}header img{width:100px}}</style><header><img src="data:image/png;base64,'+LOGO+'"><div><h1>MANUFACTURING PLAN</h1><p>Karta wymagań projektu | Zekon RFQ '+VERSION+'</p></div></header>'
    content+='<p><b>Projekt:</b> '+esc(session.project or 'Do wyjaśnienia')+'<br><b>Klient:</b> '+esc(session.client or 'Do wyjaśnienia')+'<br><b>Numer / rewizja:</b> '+esc(session.revision or 'Do wyjaśnienia')+'</p>'
    content+='<p class="note">'+('Raport automatyczny: zapisy źródłowe do weryfikacji; bez parametrów domyślnych. ' if session.automatic else 'Wymagania zawierają tylko ustalenia potwierdzone przez użytkownika. ')+'Opcje formularzy, negacje, zakres Zekon, skany i rozbieżności: do wyjaśnienia.</p>'
    content+='<h2>Karta wymagań</h2>'+table(['Obszar','Wymaganie','Źródło','Braki'],card(session))
    content+='<h2>Dodatkowe uwagi technologiczne</h2>'+table(['Temat','Parametry','Źródło','Braki','Uwagi'],tech_rows(session))
    if session.bom:content+='<h2>BOM - masa podana i obliczona oddzielnie</h2>'+table(BOM_HEADERS,session.bom)
    errors=[[i.source,i.status,i.detail] for i in session.inventory if i.status in {'Błąd','Nie przeanalizowano','BOM do wyjaśnienia'}]
    if errors:content+='<h2>Braki odczytu</h2>'+table(['Plik','Status','Brak'],errors)
    Path(path).write_text(content+'</html>',encoding='utf-8')


def save_session(session,path):
    Path(path).write_text(json.dumps({'version':VERSION,**asdict(session)},ensure_ascii=False,indent=2),encoding='utf-8')


def open_session(path):
    data=json.loads(Path(path).read_text(encoding='utf-8'))
    return Session(project=data.get('project',''),client=data.get('client',''),revision=data.get('revision',''),
        evidence=[Evidence(**e) for e in data.get('evidence',[])],inventory=[Inventory(**e) for e in data.get('inventory',[])],
        raw=data.get('raw',[]),bom=data.get('bom',[]))


def generate_automatic(paths, destination, progress=lambda *a:None):
    session=analyse(paths,progress=progress)
    session.automatic=True
    # Metadata needs explicit labels. Multiple different values remain unresolved.
    labels={'project':r'projekt|project|projet|bauvorhaben',
            'client':r'klient|client|customer|kunde|auftraggeber',
            'revision':r'numer / rewizja|document(?:ation)? number|dokumentnummer|référence document'}
    for fieldname,pattern in labels.items():
        values=[]
        for location,text in session.raw:
            for line in text.splitlines():
                match=re.fullmatch(r'\s*(?:'+pattern+r')\s*[:=]\s*(.{1,180})\s*',line,re.I)
                if match:values.append(match.group(1).strip())
        values=list(dict.fromkeys(values))
        if len(values)==1:setattr(session,fieldname,values[0])
        elif len(values)>1:setattr(session,fieldname,'Do wyjaśnienia — różne zapisy: '+'; '.join(values))
    # Recognize only a structured BOM with explicit column headers.
    for path in paths:
        if Path(path).suffix.lower() not in {'.csv','.xlsx'}:continue
        try:
            rows=load_bom(path)
            if rows:session.bom.extend(rows)
        except Exception as exc:
            session.inventory.append(Inventory(Path(path).name,'BOM do wyjaśnienia',str(exc)))
    destination=Path(destination)
    progress(len(paths),max(1,len(paths)),'Zapisywanie raportu…')
    export_xlsx(session,destination)
    export_html(session,destination.with_suffix('.html'))
    return session


class App(TkinterDnD.Tk):
    def __init__(self):
        super().__init__()
        self.title('Zekon — Analiza zapytania')
        self.geometry('720x530');self.minsize(580,440)
        self.configure(bg='#f4f5f7')
        self.paths=[];self.q=queue.Queue();self.running=False;self.last_report=None
        self.report_callback_exception=self.callback_error
        style=ttk.Style(self);style.theme_use('clam')
        style.configure('Generate.TButton',font=('Segoe UI',13,'bold'),padding=(20,14),background='#b52832',foreground='white')
        style.map('Generate.TButton',background=[('active','#92212a'),('disabled','#c8cbd0')])
        header=tk.Frame(self,bg='#f4f5f7');header.pack(fill='x',padx=28,pady=(18,12))
        self.logo=tk.PhotoImage(data=LOGO).subsample(3,3)
        tk.Label(header,image=self.logo,bg='#f4f5f7').pack(side='left')
        tk.Label(header,text='Analiza zapytania ofertowego',font=('Segoe UI',17,'bold'),bg='#f4f5f7',fg='#20272d').pack(side='left',padx=18)
        self.droparea=tk.Frame(self,bg='white',highlightbackground='#b8bec6',highlightthickness=2)
        self.droparea.pack(fill='both',expand=True,padx=28,pady=(0,16))
        self.hint=tk.Label(self.droparea,text='Przeciągnij tutaj wszystkie pliki',font=('Segoe UI',16,'bold'),bg='white',fg='#20272d')
        self.hint.pack(pady=(23,5))
        self.subhint=tk.Label(self.droparea,text='lub kliknij to pole, aby wybrać pliki\nPDF · Excel · Word · TXT · CSV · IFC · ZIP',font=('Segoe UI',10),bg='white',fg='#666e78')
        self.subhint.pack(pady=(0,12))
        self.filelist=tk.Listbox(self.droparea,bg='white',fg='#303842',font=('Segoe UI',11),bd=0,highlightthickness=0,selectmode='extended',activestyle='none')
        self.filelist.pack(fill='both',expand=True,padx=18,pady=(0,12))
        for widget in (self,self.droparea,self.hint,self.subhint,self.filelist):
            widget.drop_target_register(DND_FILES)
            widget.dnd_bind('<<Drop>>',self.drop)
        for widget in (self.droparea,self.hint,self.subhint):widget.bind('<Button-1>',self.add_files)
        self.filelist.bind('<Double-Button-1>',self.add_files)
        self.filelist.bind('<Delete>',self.remove_selected)
        self.generatebutton=ttk.Button(self,text='Generuj raport',style='Generate.TButton',command=self.start)
        self.generatebutton.pack(fill='x',padx=28)
        self.progress=ttk.Progressbar(self,mode='indeterminate')
        self.status=tk.StringVar(value='Przeciągnij pliki, następnie kliknij „Generuj raport”.')
        tk.Label(self,textvariable=self.status,font=('Segoe UI',10),bg='#f4f5f7',fg='#626b75',wraplength=640).pack(fill='x',padx=28,pady=(12,16))
        self.after(100,self.poll)

    def accept_paths(self,paths):
        if self.running:return
        if self.last_report:
            self.paths.clear();self.filelist.delete(0,'end');self.last_report=None
        for value in paths:
            p=Path(value)
            key=os.path.normcase(os.path.abspath(p))
            if any(os.path.normcase(os.path.abspath(x))==key for x in self.paths):continue
            self.paths.append(str(p));self.filelist.insert('end',p.name)
        self.status.set(f'Dodano plików: {len(self.paths)}. Kliknij „Generuj raport”.')

    def drop(self,event):
        self.accept_paths(self.tk.splitlist(event.data))
        return 'copy'

    def add_files(self,event=None):
        if self.running:return
        self.accept_paths(filedialog.askopenfilenames(title='Wybierz wszystkie materiały zapytania',filetypes=[('Materiały zapytania','*.pdf *.xlsx *.xlsm *.docx *.txt *.csv *.ifc *.zip'),('Wszystkie pliki','*.*')]))

    def remove_selected(self,event=None):
        if self.running:return
        for i in reversed(self.filelist.curselection()):self.paths.pop(i);self.filelist.delete(i)
        self.status.set(f'Dodano plików: {len(self.paths)}.')

    def start(self):
        if self.running:return
        if not self.paths:
            self.status.set('Najpierw przeciągnij pliki do białego pola.');return
        path=filedialog.asksaveasfilename(title='Gdzie zapisać raport?',initialfile='Zekon_Raport.xlsx',defaultextension='.xlsx',filetypes=[('Raport Excel','*.xlsx')])
        if not path:return
        outputs=[Path(path),Path(path).with_suffix('.html')]
        if any(os.path.normcase(os.path.abspath(out))==os.path.normcase(os.path.abspath(src)) for out in outputs for src in self.paths):
            messagebox.showerror('Miejsce zapisu','Raport nie może zastąpić pliku wejściowego. Wybierz inną nazwę.');return
        if outputs[1].exists() and not messagebox.askyesno('Istniejący raport','Zastąpić istniejący raport HTML?'):return
        self.running=True;self.generatebutton.configure(state='disabled');self.progress.pack(fill='x',padx=28,pady=(8,0));self.progress.start(15)
        self.status.set('Analizuję pliki…');paths=list(self.paths)
        def worker():
            try:
                session=generate_automatic(paths,path,lambda n,t,msg:self.q.put(('progress',msg)))
                self.q.put(('done',session,str(outputs[1])))
            except Exception:self.q.put(('error',traceback.format_exc()))
        threading.Thread(target=worker,daemon=True).start()

    def poll(self):
        try:
            while True:
                event=self.q.get_nowait()
                if event[0]=='progress':self.status.set(event[1]);continue
                self.running=False;self.generatebutton.configure(state='normal');self.progress.stop();self.progress.pack_forget()
                if event[0]=='done':
                    self.last_report=event[2]
                    failed=sum(i.status in {'Błąd','Nie przeanalizowano','BOM do wyjaśnienia'} for i in event[1].inventory)
                    self.status.set('Gotowe. Zapisano XLSX i HTML.'+(f' Pliki wymagające wyjaśnienia: {failed} — szczegóły w raporcie.' if failed else '')+' Przeciągnij kolejne zapytanie, aby rozpocząć nowy raport.')
                    try:webbrowser.open(Path(event[2]).resolve().as_uri())
                    except Exception:logging.exception('Cannot open report')
                else:
                    logging.error(event[1]);self.status.set('Nie udało się zapisać raportu.');messagebox.showerror('Raport','Nie udało się wygenerować raportu. Sprawdź uprawnienia i czy Excel nie blokuje pliku. Szczegóły zapisano w logu.')
        except queue.Empty:pass
        self.after(100,self.poll)

    def callback_error(self,exc,val,tb):
        logging.error('GUI error',exc_info=(exc,val,tb));messagebox.showerror('Błąd',str(val)+'\nSzczegóły w logu aplikacji.')


def main():
    logdir=Path(os.environ.get('LOCALAPPDATA',str(Path.home())))/'ZekonRFQ';logdir.mkdir(parents=True,exist_ok=True)
    logging.basicConfig(filename=logdir/'zekon_rfq.log',level=logging.INFO,format='%(asctime)s %(levelname)s %(message)s',encoding='utf-8')
    try:App().mainloop()
    except Exception:
        logging.exception('Startup failed')
        try:messagebox.showerror('Zekon RFQ','Nie udało się uruchomić programu. Sprawdź log: '+str(logdir/'zekon_rfq.log'))
        except Exception:pass
        raise

if __name__=='__main__':
    import sys
    if len(sys.argv)==3 and sys.argv[1]=='--smoke-test':
        window=App()
        window.update_idletasks()
        window.update()
        import tempfile
        from types import SimpleNamespace
        assert window.tk.call('package','present','tkdnd')
        with tempfile.TemporaryDirectory() as temp:
            sample=Path(temp)/'specyfikacja z odstępem.txt'
            sample.write_text('Projekt: Test\nEXC2 EN 1090-2:2018\nNELSON Kopfbolzen',encoding='utf-8')
            window.drop(SimpleNamespace(data=window.tk.call('list',str(sample))))
            assert window.paths==[str(sample)]
            report=Path(temp)/'report.xlsx'
            generate_automatic(window.paths,report)
            assert report.is_file() and report.with_suffix('.html').is_file()
        window.destroy()
        Path(sys.argv[2]).write_text('GUI startup OK',encoding='utf-8')
    else:
        main()
